components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  white-space: nowrap;
  height: 40px;
  padding: 0 16px;
  border-radius: 8px;
  background: var(--cp-accent);
  color: var(--cp-accent-ink);
  font-size: 14px;
  font-weight: 500;
  font-family: 'Inter', system-ui, sans-serif;
  border: none;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-primary:hover {
  background: oklch(35% 0.04 50 / 0.9);
}
.ds-btn-primary:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--cp-bg), 0 0 0 4px var(--cp-accent);
}
.ds-btn-primary:disabled {
  opacity: 0.5;
  pointer-events: none;
}
.ds-btn-primary svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.ds-btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 16px;
  border-radius: 8px;
  background: var(--cp-bg);
  color: var(--ink);
  border: 1px solid var(--line);
  font-size: 14px;
  font-weight: 500;
  font-family: 'Inter', system-ui, sans-serif;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-outline:hover {
  background: var(--cp-accent-soft);
  color: var(--cp-accent);
}
.ds-btn-outline:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--cp-bg), 0 0 0 4px var(--cp-accent);
}

.ds-input {
  display: flex;
  width: 100%;
  height: 40px;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--cp-bg);
  color: var(--ink);
  border: 1px solid var(--line);
  font-size: 14px;
  font-family: 'Inter', system-ui, sans-serif;
  box-sizing: border-box;
  transition: box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-input::placeholder {
  color: var(--ink-3);
}
.ds-input:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--cp-bg), 0 0 0 4px var(--cp-accent);
}
.ds-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-card {
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--cp-surface);
  color: var(--ink);
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  font-family: 'Inter', system-ui, sans-serif;
}
.ds-card-header {
  display: flex;
  flex-direction: column;
  padding: 24px;
  gap: 6px;
}
.ds-card-title {
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.025em;
  margin: 0;
  color: var(--ink);
}
.ds-card-description {
  font-size: 14px;
  color: var(--ink-3);
  margin: 0;
}
.ds-card-content {
  padding: 0 24px 24px;
  color: var(--ink-2);
}

.ds-chip-tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex: 1;
  padding: 6px 12px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  font-family: 'Inter', system-ui, sans-serif;
  background: var(--cp-bg-2);
  color: var(--ink-2);
  border: none;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-chip-tab[aria-pressed="true"] {
  background: var(--cp-surface);
  color: var(--ink);
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}
.ds-chip-tab:focus-visible {
  outline: 2px solid var(--cp-accent);
  outline-offset: 2px;
}

.ds-mobile-fab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 48px;
  padding: 0 20px;
  border-radius: 9999px;
  background: var(--cp-accent);
  color: var(--cp-accent-ink);
  font-size: 14px;
  font-weight: 500;
  font-family: 'Inter', system-ui, sans-serif;
  border: none;
  cursor: pointer;
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  transition: transform 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-mobile-fab:hover {
  transform: scale(1.02);
}
.ds-mobile-fab:active {
  transform: scale(0.95);
}
.ds-mobile-fab:focus-visible {
  outline: 2px solid var(--cp-accent);
  outline-offset: 2px;
}
.ds-mobile-fab svg {
  width: 16px;
  height: 16px;
}

.ds-dialog-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: rgb(0 0 0 / 0.8);
}
.ds-dialog-content {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 50;
  display: grid;
  width: calc(100% - 32px);
  max-width: 32rem;
  max-height: 90vh;
  transform: translate(-50%, -50%);
  gap: 16px;
  overflow-y: auto;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--cp-bg);
  padding: 24px;
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  font-family: 'Inter', system-ui, sans-serif;
  box-sizing: border-box;
  animation: ds-dialog-in 200ms ease;
}
@keyframes ds-dialog-in {
  from { opacity: 0; transform: translate(-50%, -48%) scale(0.96); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}
.ds-dialog-title {
  font-size: 18px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--ink);
}
.ds-dialog-description {
  font-size: 14px;
  color: var(--ink-3);
  margin: 0;
}
.ds-dialog-footer {
  display: flex;
  flex-direction: column-reverse;
  gap: 8px;
}
@media (min-width: 640px) {
  .ds-dialog-footer {
    flex-direction: row;
    justify-content: flex-end;
  }
}
